Yes, it's simple, nothing special.
Some smaller assets then 8kb are converted through assets management to base64 with huge output according issue description. These assets are mostly from node_modules as part of our private packages.

```
const path = require("path");

const HtmlWebpackPlugin = require("html-webpack-plugin");
const MiniCssExtractPlugin = require("mini-css-extract-plugin");
const { CleanWebpackPlugin } = require("clean-webpack-plugin");

module.exports = (env, argv) => {
    const isProduction = argv.mode === "production";
    // used as custom option for some html content to invalidate browser cache
    // when application is redeployed, used for non webpack resources
    const buildDateTime = new Date().toISOString();

    return {
        context: path.join(__dirname, "./src"),
        entry: {
            main: "./index.tsx",
        },
        output: {
            path: path.join(__dirname, "./dist"),
            filename: isProduction ? "[name].[chunkhash:4].js" : "[name].js",
            chunkFilename: isProduction ? "[id].[chunkhash:4].js" : "[id].js",
        },
        resolve: {
            // these type of files are considered as modules for import
            extensions: [".js", ".ts", ".tsx"],
            modules: [
                // consider 'src' as main module directory, so we can use use e.g. import from 'app/components/Menu'
                // it corresponds typescript tsconfig.baseUrl settings
                path.resolve(__dirname, "src"),
                "node_modules",
            ],
        },
        module: {
            rules: [
                // .ts, .tsx
                {
                    test: /\.tsx?$/,
                    // use typescript loader -> babel loader
                    use: [
                        "babel-loader", // use babel for esnext to es5
                        {
                            // transpile with typescript tsc compiler to esnext
                            loader: "ts-loader",
                            options: {
                                onlyCompileBundledFiles: true,
                            },
                        },
                    ],
                },
                // sass
                {
                    test: /\.scss$/,
                    use: [isProduction ? MiniCssExtractPlugin.loader : "style-loader", "css-loader", "sass-loader"],
                },
                // css
                {
                    test: /\.css?$/,
                    use: [isProduction ? MiniCssExtractPlugin.loader : "style-loader", "css-loader"],
                },
                // images, graphics
                {
                    test: /\.(png|jpg|jpeg|gif|woff|woff2|eot|ttf|svg)$/,
                    type: "asset",
                },
            ],
        },
        plugins: [
            // extract all styles
            new MiniCssExtractPlugin({
                filename: isProduction ? "[name].[contenthash:4].css" : "[name].css",
                chunkFilename: isProduction ? "[id].[chunkhash:4].js" : "[id].js",
            }),
            // cleans or creates dist folder
            new CleanWebpackPlugin(),
            // process main page as template, must be presented after css extract plugins
            new HtmlWebpackPlugin({
                template: "assets/index-template.html",
                favicon: "assets/favicon.ico",
                filename: "index.html",
                chunks: ["main", "initLoading"],
                hash: true,
                // custom options for invalidate non webpack html resources
                buildDateTime: buildDateTime,
            }),
        ],
        devServer: {
            hot: false,
            liveReload: true,
            static: {
                directory: path.resolve(__dirname + "/web-content"),
            },
            // all paths are rewritten into index.html, same as on deployed web servers
            historyApiFallback: true,
            open: true,
        },
        watchOptions: {
            // ignore watch for node_modules, be aware, this is no string, it's regular expression
            ignored: /node_modules/,
        },
        devtool: isProduction ? "source-map" : "eval-cheap-module-source-map",
    };
};
```
